        var title=new Panel{Dock=DockStyle.Fill};title.Controls.Add(new Label{Text="Dashboard",Location=new Point(0,0),AutoSize=true,Font=new Font("Segoe UI",25,FontStyle.Bold),ForeColor=Txt});title.Controls.Add(new Label{Text="Monitor and control your Bluetooth audio environment",Location=new Point(2,48),AutoSize=true,ForeColor=Muted});root.Controls.Add(title,0,0);
