        var hero=CardPanel();hero.Margin=new Padding(0,14,0,8);var grid=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,BackColor=Card,Padding=new Padding(18),Margin=Padding.Empty};grid.RowStyles.Add(new RowStyle(SizeType.Absolute,52));grid.RowStyles.Add(new RowStyle(SizeType.Percent,100));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,58));grid.RowStyles.Add(new RowStyle(SizeType.Absolute,36));
