        grid.Controls.Add(h,0,0);grid.Controls.Add(new WavePanel{Dock=DockStyle.Fill,Margin=new Padding(0,0,0,10),BackColor=Deep},0,1);toggle=Btn(audio.State is AudioEngineState.Running or AudioEngineState.PausedByOtherAudio?"■   Stop Keep-Alive":"▶   Start Keep-Alive",true);toggle.Dock=DockStyle.Fill;toggle.Margin=new Padding(0,0,0,8);toggle.Click+=(_,_)=>audio.Toggle();grid.Controls.Add(toggle,0,2);
        var stateBox=new Panel{Dock=DockStyle.Fill,BackColor=Deep};stateLabel=new Label{Text="Ready to keep audio active",Dock=DockStyle.Fill,Padding=new Padding(12,0,0,0),TextAlign=ContentAlignment.MiddleLeft,ForeColor=Muted};stateBox.Controls.Add(stateLabel);grid.Controls.Add(stateBox,0,3);hero.Controls.Add(grid);root.Controls.Add(hero,0,2);
