    Control Metric(string n,string title,string value,string sub){var p=CardPanel();p.Margin=new Padding(0,0,10,0);p.Controls.Add(new Label{Text=n+"   "+title,Location=new Point(12,9),AutoSize=true,ForeColor=Muted,Font=new Font("Segoe UI",7.5F,FontStyle.Bold)});p.Controls.Add(new Label{Text=value,Location=new Point(12,34),Size=new Size(230,30),AutoEllipsis=true,ForeColor=Txt,Font=new Font("Segoe UI Semibold",14,FontStyle.Bold)});p.Controls.Add(new Label{Text=sub,Location=new Point(12,72),Size=new Size(230,20),AutoEllipsis=true,ForeColor=Muted,Font=new Font("Segoe UI",8)});return p;}
    void DevicePage(){var root=Page("Audio Device","Select the Windows playback endpoint used by the silent stream.");var card=CardPanel();card.Controls.Add(new Label{Text="PLAYBACK OUTPUT DEVICE",Location=new Point(22,22),AutoSize=true,ForeColor=Pink2,Font=new Font("Segoe UI",9,FontStyle.Bold)});var combo=new ComboBox{Location=new Point(22,58),Width=Math.Max(300,_pageHost.ClientSize.Width-90),DropDownStyle=ComboBoxStyle.DropDownList,BackColor=Deep,ForeColor=Txt,FlatStyle=FlatStyle.Flat};var ds=AudioDeviceService.GetPlaybackDevices();foreach(var d in ds)combo.Items.Add(d);combo.DisplayMember="Name";combo.SelectedIndex=Math.Max(0,ds.FindIndex(d=>d.DeviceNumber==settings.PreferredDeviceNumber));var save=Btn("Save Device",true);save.Location=new Point(22,112);save.Size=new Size(160,42);save.Click+=(_,_)=>{if(combo.SelectedItem is AudioDeviceInfo d){settings.PreferredDeviceNumber=d.DeviceNumber;settings.PreferredDeviceName=d.Name;settings.Save();audio.PreferredDeviceName=d.Name;audio.TargetDeviceNumber=d.DeviceNumber;device.Text="Playback output · "+d.Name;Navigate("Dashboard");}};card.Controls.Add(combo);card.Controls.Add(save);root.Controls.Add(card,0,2);_pageHost.Controls.Add(root);}
