    void SettingsPage()
    {
        var root = Page("Settings", "Preferences are saved locally on this Windows account.");
        var card = CardPanel();
        var autoStart = Check("Start stream when app opens", settings.AutoStartStreamOnLaunch);
        var minimize = Check("Start minimized to tray", settings.StartMinimizedToTray);
        var minimizeClose = Check("Minimize to tray when window closes", settings.MinimizeToTrayOnClose);
        var notifications = Check("Show Windows notifications", settings.ShowNotifications);
        var startup = Check("Launch app when I sign in to Windows", settings.StartOnWindowsStartup);
        var checks = new[] { autoStart, minimize, minimizeClose, notifications, startup };
        for (int i = 0; i < checks.Length; i++)
        {
            checks[i].Location = new Point(22, 24 + i * 42);
            card.Controls.Add(checks[i]);
        }
        autoStart.CheckedChanged += (_, _) => { settings.AutoStartStreamOnLaunch = autoStart.Checked; settings.Save(); };
        minimize.CheckedChanged += (_, _) => { settings.StartMinimizedToTray = minimize.Checked; settings.Save(); };
        minimizeClose.CheckedChanged += (_, _) => { settings.MinimizeToTrayOnClose = minimizeClose.Checked; settings.Save(); };
        notifications.CheckedChanged += (_, _) => { settings.ShowNotifications = notifications.Checked; settings.Save(); };
        startup.CheckedChanged += (_, _) => { settings.StartOnWindowsStartup = startup.Checked; settings.Save(); };
        root.Controls.Add(card, 0, 2);
        _pageHost.Controls.Add(root);
    }
    void AboutPage(){var root=Page("About & Updates","Windows desktop utility for maintaining a Bluetooth audio endpoint.");var card=CardPanel();card.Controls.Add(new Label{Text="HOCO KeepAlive",Location=new Point(22,22),AutoSize=true,Font=new Font("Segoe UI",18,FontStyle.Bold),ForeColor=Txt});card.Controls.Add(new Label{Text="Version 1.0.7 · Windows 10/11 x64",Location=new Point(22,60),AutoSize=true,ForeColor=Pink2});card.Controls.Add(new Label{Text="Designed for HOCO HC22 and other Bluetooth playback devices.",Location=new Point(22,94),AutoSize=true,ForeColor=Muted});var b=Btn("Open GitHub Repository",false);b.Location=new Point(22,136);b.Size=new Size(210,42);b.Click+=(_,_)=>{try{Process.Start(new ProcessStartInfo("https://github.com/tausif-rahaman-raiyan/HocoKeepAlive"){UseShellExecute=true});}catch{}};card.Controls.Add(b);root.Controls.Add(card,0,2);_pageHost.Controls.Add(root);}
    TableLayoutPanel Page(string title,string sub){var r=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=3,BackColor=Bg,Margin=Padding.Empty,Padding=Padding.Empty};r.RowStyles.Add(new RowStyle(SizeType.Absolute,92));r.RowStyles.Add(new RowStyle(SizeType.Absolute,10));r.RowStyles.Add(new RowStyle(SizeType.Percent,100));var h=new Panel{Dock=DockStyle.Fill};h.Controls.Add(new Label{Text=title,Location=new Point(0,0),AutoSize=true,Font=new Font("Segoe UI",23,FontStyle.Bold),ForeColor=Txt});h.Controls.Add(new Label{Text=sub,Location=new Point(2,48),AutoSize=true,ForeColor=Muted});r.Controls.Add(h,0,0);return r;}
    Panel CardPanel(){var p=new Panel{Dock=DockStyle.Fill,BackColor=Card,Padding=new Padding(18),Margin=Padding.Empty};p.Paint+=(_,e)=>{using var pen=new Pen(Line);e.Graphics.DrawRectangle(pen,0,0,p.Width-1,p.Height-1);};return p;}
    Button Btn(string text,bool primary){var b=new Button{Text=text,FlatStyle=FlatStyle.Flat,BackColor=primary?Pink:Deep,ForeColor=Txt,Font=new Font("Segoe UI Semibold",9,FontStyle.Bold),Cursor=Cursors.Hand,UseVisualStyleBackColor=false,Height=42,Margin=Padding.Empty};b.FlatAppearance.BorderSize=1;b.FlatAppearance.BorderColor=primary?Pink:Line;b.FlatAppearance.MouseOverBackColor=primary?Pink2:Color.FromArgb(45,26,34);return b;}
    CheckBox Check(string text,bool value)=>new(){Text=text,Checked=value,AutoSize=true,ForeColor=Txt,BackColor=Card,Font=new Font("Segoe UI",9),FlatStyle=FlatStyle.Flat};
    static string Short(string s,int n)=>string.IsNullOrWhiteSpace(s)?"Windows Default":s.Length>n?s[..(n-1)]+"…":s;
    string StateName()=>audio.State switch{AudioEngineState.Running=>"Running",AudioEngineState.PausedByOtherAudio=>"Standby",AudioEngineState.Recovering=>"Reconnecting",AudioEngineState.DeviceUnavailable=>"Offline",AudioEngineState.Error=>"Error",_=>"Stopped"};
    string Duration()=>audio.RunningDuration is TimeSpan d?d.ToString(@"hh\:mm\:ss"):"00:00:00";
    void OnState(AudioEngineState s,string? m){if(IsDisposed||!IsHandleCreated)return;try{BeginInvoke(new Action(UpdateState));}catch(InvalidOperationException){}}
    void UpdateState(){if(IsDisposed)return;var s=audio.State;bool active=s is AudioEngineState.Running or AudioEngineState.PausedByOtherAudio or AudioEngineState.Recovering;status.Text=s switch{AudioEngineState.Running=>"●  RUNNING",AudioEngineState.PausedByOtherAudio=>"●  STANDBY",AudioEngineState.Recovering=>"●  RECONNECTING",AudioEngineState.DeviceUnavailable=>"●  DEVICE OFFLINE",AudioEngineState.Error=>"●  ERROR",_=>"●  STOPPED"};status.ForeColor=active?Color.FromArgb(89,222,158):Pink2;if(toggle!=null)toggle.Text=active?"■   Stop Keep-Alive":"▶   Start Keep-Alive";if(stateLabel!=null)stateLabel.Text=s switch{AudioEngineState.Running=>"Silent stream active · Bluetooth output held awake",AudioEngineState.PausedByOtherAudio=>"Standby · other audio detected; endpoint released",AudioEngineState.Recovering=>"Reconnecting to playback device…",AudioEngineState.DeviceUnavailable=>"Device unavailable · check Bluetooth connection",AudioEngineState.Error=>"Audio engine error · "+(audio.LastError??"Unknown error"),_=>"Ready to keep audio active"};device.Text="Playback output · "+settings.PreferredDeviceName;}
    void OnClosing(object? sender,FormClosingEventArgs e){if(!allowClose&&e.CloseReason==CloseReason.UserClosing){if(settings.MinimizeToTrayOnClose){e.Cancel=true;Hide();}else{e.Cancel=true;exit();}}}
    public void CloseForExit(){allowClose=true;timer.Stop();audio.StateChanged-=OnState;Close();}
    protected override void OnFormClosed(FormClosedEventArgs e){timer.Stop();timer.Dispose();audio.StateChanged-=OnState;base.OnFormClosed(e);}
    sealed class WavePanel:Panel{readonly System.Windows.Forms.Timer t=new(){Interval=50};double phase;public WavePanel(){DoubleBuffered=true;t.Tick+=(_,_)=>{phase+=.075;Invalidate();};t.Start();Disposed+=(_,_)=>t.Dispose();}protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);e.Graphics.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;int w=Width,h=Height;if(w<20||h<20)return;using var glow=new Pen(Color.FromArgb(30,Pink),13);using var mid=new Pen(Color.FromArgb(100,Pink2),4);using var core=new Pen(Pink2,1.5f);for(int lane=0;lane<4;lane++){var pts=new List<PointF>();for(int x=0;x<w;x+=3){double q=(double)x/w;double y=h*.5+Math.Sin(q*12+phase+lane*.75)*h*(.12+.12*Math.Sin(q*4+lane))+Math.Sin(q*23-phase*.7+lane)*h*.045;pts.Add(new PointF(x,(float)y));}if(pts.Count>1){e.Graphics.DrawLines(glow,pts.ToArray());e.Graphics.DrawLines(mid,pts.ToArray());e.Graphics.DrawLines(core,pts.ToArray());}}}}
